import { createRoot } from 'react-dom/client';
import './index.css';
import * as React from 'react';
import { useEffect, useState, useRef } from 'react';
import { GanttComponent, Inject, Selection, ColumnsDirective, ColumnDirective, VirtualScroll } from '@syncfusion/ej2-react-gantt';
import { DataManager, WebApiAdaptor } from '@syncfusion/ej2-data';

import { DropDownListComponent } from '@syncfusion/ej2-react-dropdowns';
const RemoteData = () => {
    const recordCount = useRef("1000");
    const dataSource = new DataManager({
        url: `https://services.syncfusion.com/react/production/api/GanttWebApiRemoteData?count=${recordCount.current}`,
        adaptor: new WebApiAdaptor(),
        crossDomain: true
    });
    const [loadTime, setLoadTime] = useState("");
    const [startLoadTime, setStartLoadTime] = useState(new Date());
    const shouldCalculateLoadTime = useRef(true);
    const dropdownData = [
        { Text: "1,000 Rows", Value: "1000" },
        { Text: "2,500 Rows", Value: "2500" },
        { Text: "5,000 Rows", Value: "5000" },
    ];
    const dropdownFields = { text: "Text", value: "Value" };
    const taskFields = {
        id: "TaskId",
        name: "TaskName",
        startDate: "StartDate",
        endDate: "EndDate",
        duration: "Duration",
        progress: "Progress",
        parentID: "ParentId",
        dependency: "Predecessor",
    };
    const projectStartDate = new Date("12/29/2024");
    const projectEndDate = new Date("03/19/2025");
    const gridLines = "Horizontal";
    const timelineSettings = {
        timelineUnitSize: 50,
        topTier: {
            unit: 'Week',
            format: 'MMM dd, y',
        },
        bottomTier: {
            unit: 'Day',
            format: 'dd'
        },
    };
    const labelSettings = {
        rightLabel: "TaskName",
        taskLabel: "Progress"
    };
    const loadGanttData = () => {
        setStartLoadTime(new Date());
        shouldCalculateLoadTime.current = true;
    };
    const splitterSettings = {
        columnIndex: 2
    };
    const onDropdownChange = (e) => {
        recordCount.current = e.value;
        loadGanttData();
    };
    const onDataBound = () => {
        if (shouldCalculateLoadTime.current && startLoadTime) {
            shouldCalculateLoadTime.current = false;
            const endLoadTime = new Date();
            const diff = endLoadTime.getTime() - startLoadTime.getTime();
            setLoadTime((diff / 1000).toFixed(2));
        }
    };
    return (<div className='control-pane'>
      <div className='control-section'>
        <div style={{ display: "flex", }}>
          <div style={{ width: "130px", paddingBottom: "10px" }}>
            <DropDownListComponent dataSource={dropdownData} fields={dropdownFields} value={recordCount} change={onDropdownChange} placeholder="1,000 Rows"/>
          </div>
          <span style={{ paddingLeft: "20px", fontSize: "15px", marginTop: "5px" }}>
            <b>Data initial load time:</b> {loadTime} sec
          </span>
        </div>
        <GanttComponent id='RemoteData' dataSource={dataSource} allowSorting={true} dateFormat={'MMM dd, y'} treeColumnIndex={1} allowSelection={true} highlightWeekends={false} includeWeekend={true} splitterSettings={splitterSettings} allowUnscheduledTasks={true} projectStartDate={projectStartDate} projectEndDate={projectEndDate} enableVirtualization={true} enableTimelineVirtualization={true} taskFields={taskFields} gridLines={gridLines} timelineSettings={timelineSettings} labelSettings={labelSettings} dataBound={onDataBound} height='650px' rowHeight={46} taskbarHeight={25}>
          <ColumnsDirective>
            <ColumnDirective field='TaskId'></ColumnDirective>
            <ColumnDirective field='TaskName' headerText="Project Activity" width='250' clipMode='EllipsisWithTooltip'></ColumnDirective>
            <ColumnDirective field='StartDate' headerText="Planned Start Date"></ColumnDirective>
            <ColumnDirective field="Duration" headerText="Duration"></ColumnDirective>
            <ColumnDirective field="Progress" headerText="Completion (%)"></ColumnDirective>
          </ColumnsDirective>
          <Inject services={[Selection, VirtualScroll]}/>
        </GanttComponent>
        <div style={{ float: 'right', margin: '10px' }}>Source:
          <a href="https://en.wikipedia.org/wiki/Cereal_growth_staging_scales" target='_blank'>https://en.wikipedia.org/</a>
        </div>
      </div>

    </div>);
};
export default RemoteData;

const root = createRoot(document.getElementById('sample'));
root.render(<RemoteData />);
